const fs = require('fs');
const path = require('path');

const dir = __dirname;
const inFile = path.join(dir, 'config.json');
const outFile = path.join(dir, 'config.out.json');

let config = {};
try {
  config = JSON.parse(fs.readFileSync(inFile, 'utf8'));
} catch (err) {
  console.error(`Failed to read ${inFile}: ${err.message}`);
  process.exit(1);
}

if (config.port === undefined) config.port = 3000;
if (config.host === undefined) config.host = '127.0.0.1';

fs.writeFileSync(outFile, JSON.stringify(config, null, 2) + '\n');
console.log(`Wrote ${outFile}`);

